function render(){document.querySelector('#turnLabel').textContent=`DIA ${String(state.day).padStart(2,'0')}`;renderResources();renderIntel();renderDetail();drawMap();$('#endTurn').disabled=state.over}
const outline=[[.12,.34],[.18,.23],[.29,.19],[.38,.13],[.52,.17],[.62,.12],[.73,.19],[.86,.18],[.91,.29],[.88,.41],[.92,.52],[.85,.61],[.87,.72],[.78,.82],[.66,.86],[.57,.82],[.47,.9],[.36,.84],[.27,.87],[.18,.78],[.12,.68],[.09,.55],[.13,.46]];
function screen(p){return [canvas.width*(.04+p[0]*.92),canvas.height*(.04+p[1]*.92)]}
function pathOutline(){ctx.beginPath();outline.forEach((p,i)=>{let [x,y]=screen(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath()}
function cellPoly(i){let p=[regions[i].x,regions[i].y],poly=[[0,0],[1,0],[1,1],[0,1]];for(let j=0;j<regions.length;j++){if(i===j)continue;let q=[regions[j].x,regions[j].y],nx=q[0]-p[0],ny=q[1]-p[1],c=(q[0]*q[0]+q[1]*q[1]-p[0]*p[0]-p[1]*p[1])/2,next=[];for(let k=0;k<poly.length;k++){let a=poly[k],b=poly[(k+1)%poly.length],da=nx*a[0]+ny*a[1]-c,db=nx*b[0]+ny*b[1]-c,ina=da<=0,inb=db<=0;if(ina)next.push(a);if(ina!==inb){let t=da/(da-db);next.push([a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t])}}poly=next}return poly}
function drawMap(){let rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,rect.width),h=Math.max(1,rect.height);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);let W=w,H=h;ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(W/2+state.offsetX,H/2+state.offsetY);ctx.scale(state.zoom,state.zoom);ctx.translate(-W/2,-H/2);
// cartographic grid
ctx.strokeStyle='#b9d1bd0b';ctx.lineWidth=1;for(let x=28;x<W;x+=38){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=15;y<H;y+=38){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
// country shadow and clipped Voronoi territories
pathOutline();ctx.save();ctx.shadowColor='#080c09';ctx.shadowBlur=22;ctx.shadowOffsetY=8;ctx.fillStyle='#24342b';ctx.fill();ctx.restore();pathOutline();ctx.clip();
regions.forEach((r,i)=>{let poly=cellPoly(i);ctx.beginPath();poly.forEach((p,j)=>{let [x,y]=screen(p);j?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();let s=status(r);ctx.fillStyle=s==='resistance'?'#477664':s==='regime'?'#8f493e':'#8d7742';ctx.fill();ctx.strokeStyle='#d5dfbd36';ctx.lineWidth=1;ctx.stroke();let [x,y]=screen([r.x,r.y]);let selected=r.id===state.selected;ctx.beginPath();ctx.arc(x,y,selected?55:48,0,Math.PI*2);let g=ctx.createRadialGradient(x,y,5,x,y,selected?55:48);g.addColorStop(0,'#10171300');g.addColorStop(1,'#101713aa');ctx.fillStyle=g;ctx.fill()});
// supply routes
ctx.setLineDash([4,5]);ctx.lineWidth=1.5;ctx.strokeStyle='#e2d4a25a';regions.forEach(r=>r.neighbors.forEach(id=>{let b=regions.find(z=>z.id===id);if(!b||r.id>b.id)return;let a=screen([r.x,r.y]),c=screen([b.x,b.y]);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...c);ctx.stroke()}));ctx.setLineDash([]);
pathOutline();ctx.lineWidth=2;ctx.strokeStyle='#d8d1ad';ctx.stroke();ctx.restore();
// province markers + labels
regions.forEach(r=>{let [x,y]=screen([r.x,r.y]),s=status(r),color=s==='resistance'?'#a7d8b5':s==='regime'?'#ed9a83':'#f0d17a',selected=r.id===state.selected;ctx.beginPath();ctx.arc(x,y,selected?8:6,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.lineWidth=selected?2:1;ctx.strokeStyle='#152019';ctx.stroke();if(r.id==='capital'){ctx.beginPath();ctx.arc(x,y,12,0,Math.PI*2);ctx.strokeStyle='#f1d27b';ctx.lineWidth=1.3;ctx.stroke();ctx.fillStyle='#fff0b0';ctx.font='12px sans-serif';ctx.fillText('★',x-4,y-15)}ctx.font=`${selected?'700 ':''}${Math.max(9,Math.min(11,W/68))}px system-ui`;ctx.textAlign='center';ctx.textBaseline='top';ctx.lineWidth=3;ctx.strokeStyle='#111913';ctx.strokeText(r.name,x,y+11);ctx.fillStyle=selected?'#fff5da':'#e0e5d7';ctx.fillText(r.name,x,y+11)});
ctx.restore()}
function selectRegion(x,y){let rect=canvas.getBoundingClientRect(),px=x-rect.left,py=y-rect.top,W=rect.width,H=rect.height;px=(px-W/2-state.offsetX)/state.zoom+W/2;py=(py-H/2-state.offsetY)/state.zoom+H/2;let closest=regions.map(r=>{let [rx,ry]=screen([r.x,r.y]);return {r,d:Math.hypot(px-rx,py-ry)}}).sort((a,b)=>a.d-b.d)[0];if(closest&&closest.d<Math.min(W,H)*.18){state.selected=closest.r.id;renderDetail();drawMap()}}
canvas.addEventListener('click',e=>selectRegion(e.clientX,e.clientY));
window.addEventListener('resize',drawMap);

