window.addEventListener('resize',drawMap);
function act(){if(state.over)return;let r=regions.find(x=>x.id===state.selected);if(!r){showToast('Selecione um território primeiro.');return}if(state.action==='mobilize'){if(state.supplies<2){showToast('Suprimentos insuficientes.');return}state.supplies-=2;r.support=clamp(r.support+7);r.enemy=clamp(r.enemy-17);state.morale=clamp(state.morale+2);log('Brigadas mobilizadas',`A resistência reforçou ${r.name}.`)}else if(state.action==='rally'){if(state.supplies<1){showToast('Suprimentos insuficientes.');return}state.supplies-=1;r.support=clamp(r.support+13);r.unrest=clamp(r.unrest+9);state.legitimacy=clamp(state.legitimacy+2);state.morale=clamp(state.morale+3);log('As ruas respondem',`A convocação popular em ${r.name} atraiu novos apoiadores.`)}else{if(state.intel<2){showToast('Inteligência insuficiente.');return}state.intel-=2;r.enemy=clamp(r.enemy-19);r.support=clamp(r.support+3);r.unrest=clamp(r.unrest+12);state.regime=clamp(state.regime-4);log('Operação clandestina',`Uma ação de sabotagem desorganizou o regime em ${r.name}.`)}if(controlled(r)){state.legitimacy=clamp(state.legitimacy+1);showToast(`${r.name} está sob controle da Frente!`)}render();save()}
function nextDay(){if(state.over)return;let liberated=regions.filter(controlled).length;let targets=regions.filter(r=>r.enemy>24&&r.support>28);targets.sort((a,b)=>a.enemy-b.enemy);let target=targets[Math.floor(Math.random()*Math.min(3,targets.length))];if(target){let pressure=4+Math.floor(Math.random()*5);target.enemy=clamp(target.enemy+pressure);if(target.enemy>48&&Math.random()<.42)target.support=clamp(target.support-3);log('Contraofensiva do regime',`Patrulhas avançaram sobre ${target.name} (+${pressure}% de presença).`)}state.regime=clamp(state.regime+(liberated>=5?2:4));state.supplies=clamp(state.supplies+2+(regions.some(r=>r.id==='porto'&&controlled(r))?1:0),0,20);state.intel=clamp(state.intel+1,0,12);if(liberated>=4)state.morale=clamp(state.morale+2);else state.morale=clamp(state.morale-2);if(regions.some(r=>r.id==='porto'&&controlled(r)))state.legitimacy=clamp(state.legitimacy+1);state.day++;let capital=regions.find(r=>r.id==='capital');if(controlled(capital)&&liberated>=8&&state.legitimacy>=40){finish(true);return}if(state.regime>=100||state.morale<=0||state.day>15){finish(false);return}render();save()}
