+function nextDay(){if(state.over)return;let liberated=regions.filter(controlled).length;let targets=regions.filter(r=>r.enemy>24&&r.support>28);targets.sort((a,b)=>a.enemy-b.enemy);let target=targets[Math.floor(Math.random()*Math.min(3,targets.length))];if(target){let pressure=4+Math.floor(Math.random()*5);target.enemy=clamp(target.enemy+pressure);if(target.enemy>48&&Math.random()<.42)target.support=clamp(target.support-3);log('Contraofensiva do regime',`Patrulhas avançaram sobre ${target.name} (+${pressure}% de presença).`)}state.regime=clamp(state.regime+(liberated>=5?2:4));state.supplies=clamp(state.supplies+2+(regions.some(r=>r.id==='porto'&&controlled(r))?1:0),0,20);state.intel=clamp(state.intel+1,0,12);if(liberated>=4)state.morale=clamp(state.morale+2);else state.morale=clamp(state.morale-2);if(regions.some(r=>r.id==='porto'&&controlled(r)))state.legitimacy=clamp(state.legitimacy+1);state.day++;state.acted=false;let capital=regions.find(r=>r.id==='capital');if(controlled(capital)&&liberated>=8&&state.legitimacy>=40){finish(true);return}if(state.regime>=100||state.morale<=0||state.day>15){finish(false);return}render();save()}
 function finish(win){state.over=true;$('#resultHeading').textContent=win?'A aurora chegou.':'A revolta foi silenciada.';$('#resultSub').textContent=win?'VESPERIA LIVRE':'FIM DA OPERAÇÃO · DIA '+String(state.day).padStart(2,'0');$('#resultText').textContent=win?'A Frente de Libertação tomou Nova Aurora e conquistou apoio suficiente para formar um governo de transição. O futuro agora pertence ao povo.':state.regime>=100?'O regime declarou estado de emergência e isolou as brigadas. A resistência precisará se reorganizar.':state.morale<=0?'Sem esperança e sem coesão, as brigadas depuseram as armas.':'Quinze dias se passaram. O regime consolidou suas posições antes que a Frente pudesse chegar à capital.';$('#result').classList.remove('hidden');$('#endTurn').disabled=true;save()}
 function fresh(){state={day:1,supplies:10,intel:6,morale:62,legitimacy:34,regime:56,selected:'porto',action:'mobilize',acted:false,over:false,zoom:1,offsetX:0,offsetY:0,log:[],sound:false};regions.forEach(r=>{let base={capital:[25,82,38],porto:[46,39,55],montes:[68,20,64],fronteira:[59,28,49],planalto:[49,44,43],norte:[54,36,47],leste:[36,59,61],sul:[48,43,45],vale:[62,31,54],costa:[57,34,58],serra:[66,25,57],estepe:[31,65,35]}[r.id];[r.support,r.enemy,r.unrest]=base});log('Sinal recebido','A Operação Aurora está autorizada. As brigadas aguardam suas ordens.');$('#intro').classList.add('hidden');$('#result').classList.add('hidden');render();save()}
 function save(){try{localStorage.setItem('vesperia-save',JSON.stringify({state,regions:regions.map(r=>({id:r.id,support:r.support,enemy:r.enemy,unrest:r.unrest}))}))}catch(e){}}
 function load(){try{let data=JSON.parse(localStorage.getItem('vesperia-save')||'null');if(data&&data.state&&!data.state.over){Object.assign(state,data.state);(data.regions||[]).forEach(saved=>{let r=regions.find(x=>x.id===saved.id);if(r)Object.assign(r,{support:saved.support,enemy:saved.enemy,unrest:saved.unrest})});$('#intro').classList.add('hidden');log('Rádio em silêncio','Operação retomada do último relatório.')}}catch(e){}}
